import requests

url = "https://api.staging.deliverect.io/catalog/accounts/{accountId}/itemsUploadUrl"

payload = {'callbackUrl': 'https://example.com/itemsCallback'}  
headers = {'Authorization': 'Bearer {TOKEN}'}

response = requests.post(url, headers=headers, json=payload)

print(response.text)

